List<String> separateParenGroups(String parenString) {
  List<String> result = [];
  List<String> currentString = [];
  int currentDepth = 0;

  for (int i = 0; i < parenString.length; i++) {
    String c = parenString[i];
    if (c == '(') {
      currentDepth += 1;
      currentString.add(c);
    } else if (c == ')') {
      currentDepth -= 1;
      currentString.add(c);

      if (currentDepth == 0) {
        result.add(currentString.join(''));
        currentString.clear();
      }
    }
  }

  return result;
}

@pragma('vm:entry-point')
void main() {
  // Test case 1
  List<String> result1 = separateParenGroups("( ) (( )) (( )( ))");
  print(result1);
  assert(result1.length == 3);
  assert(result1[0] == "()");
  assert(result1[1] == "(())");
  assert(result1[2] == "(()())");

